namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    public static int DiscountCents(int subtotalCents, LoyaltyTier loyaltyTier) =>
        subtotalCents * RatePercent(loyaltyTier) / 100;

    private static int RatePercent(LoyaltyTier loyaltyTier) => loyaltyTier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier))
    };
}

