    [InlineData(10_000, LoyaltyTier.Silver, "WELCOME5", false, 8_500, 0, 8_500)]
    [InlineData(5_000, LoyaltyTier.Bronze, null, false, 4_750, 490, 5_240)]
    [InlineData(20_000, LoyaltyTier.Platinum, "SUMMER10", true, 16_500, 0, 16_500)]
    [InlineData(2_000, LoyaltyTier.Gold, null, true, 2_000, 990, 2_990)]
    public void S14_CheckoutQuoteAddsShippingToPayableTotal(
        int subtotal, LoyaltyTier tier, string? code, bool express, int payable, int fee, int total)
    {
        var quote = new QuoteCheckout().Handle(new QuoteCheckoutQuery(subtotal, tier, code, express));

        Assert.Equal(new Application.CheckoutQuote(payable, fee, total), quote);
    }
}
EOF
